css:
.lg-banner {
  position: relative;
  width: 100%;
  height: 260px;
  overflow: hidden;
  background: #f4f4f2;
}

.lg-banner .orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}

.lg-banner .orb-1 {
  width: 220px;
  height: 220px;
  top: -60px;
  left: 8%;
  background: radial-gradient(circle at 35% 30%, #1c1c1e, #000 70%);
  animation: lg-float-a 16s ease-in-out infinite;
}

.lg-banner .orb-2 {
  width: 160px;
  height: 160px;
  bottom: -50px;
  left: 30%;
  background: #ffffff;
  box-shadow: 0 0 60px rgba(0, 0, 0, 0.06);
  animation: lg-float-b 18s ease-in-out infinite;
}

.lg-banner .orb-3 {
  width: 260px;
  height: 260px;
  top: -80px;
  left: 55%;
  background: radial-gradient(circle at 40% 35%, #3a3a3c, #000 75%);
  animation: lg-float-a 20s ease-in-out infinite reverse;
}

.lg-banner .orb-4 {
  width: 130px;
  height: 130px;
  bottom: -40px;
  left: 78%;
  background: #ffffff;
  box-shadow: 0 0 50px rgba(0, 0, 0, 0.05);
  animation: lg-float-b 15s ease-in-out infinite reverse;
}

@keyframes lg-float-a {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  50% {
    transform: translate(30px, 40px) scale(1.08);
  }
}

@keyframes lg-float-b {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  50% {
    transform: translate(-25px, -30px) scale(0.94);
  }
}

.lg-banner .glass-sheet {
  position: absolute;
  inset: 0;
  backdrop-filter: blur(28px) saturate(160%);
  -webkit-backdrop-filter: blur(28px) saturate(160%);
  background: rgba(255, 255, 255, 0.14);
}

.lg-banner .track {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  animation: lg-drift 22s linear infinite;
}

.lg-banner .bar {
  flex: 0 0 auto;
  width: 90px;
  height: 150px;
  margin: 0 26px;
  border-radius: 26px;
  background: rgba(255, 255, 255, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.9),
    inset 0 -6px 10px rgba(0, 0, 0, 0.05),
    0 8px 24px rgba(0, 0, 0, 0.06);
}

.lg-banner .bar.dark {
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.25),
    inset 0 -6px 10px rgba(0, 0, 0, 0.4),
    0 8px 24px rgba(0, 0, 0, 0.15);
}

@keyframes lg-drift {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .lg-banner .orb,
  .lg-banner .track {
    animation: none;
  }
}
